 if(select current_plan_revision_id from tongs.reference_visual_plan_sequences where workspace_id='82000000-0000-4000-8000-000000000001'and workpiece_id='83000000-0000-4000-8000-000000000001')=new_plan then raise exception 'source removal did not advance the plan';end if;
end $source_reassignment$;
rollback;
